#include "layer_metadata.h"
#include "document.h"
#include "project_encode.h"
#include "project_import.h"
#include <iostream>
#include <cmath>
#include <stdexcept>
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
using namespace moon;
void groupProperties(){Document d(1,1);d.selectTimelineLayer(d.layer().id);CHECK(d.createLayerGroup());auto id=*d.selectedGroupId();d.selectTimelineRow({LayerPanelKind::Group,id,0});d.markSaved();auto h=d.historySize();d.beginLayerProperties({id});d.previewLayerName(U" parent ");d.previewLayerOpacity(.4);d.previewLayerBlendMode("screen");d.previewLayerDisplayColor(0x80403020);d.previewLayerDescription(U" note ");CHECK(!d.dirty()&&d.historySize()==h);d.cancelLayerOpacity();CHECK(d.findGroup(id)->opacity==1&&d.findGroup(id)->description.empty()&&!d.dirty());d.beginLayerProperties({id});d.previewLayerName(U" parent ");d.previewLayerOpacity(.4);d.previewLayerDisplayColor(0x80403020);d.previewLayerDescription(U" note ");d.commitLayerOpacity();CHECK(d.findGroup(id)->name==U"parent"&&d.findGroup(id)->description==U"note"&&d.findGroup(id)->opacity==.4&&d.historySize()==h+1);d.undo();CHECK(d.findGroup(id)->opacity==1&&d.findGroup(id)->description.empty());d.redo();CHECK(d.findGroup(id)->displayColor==0x80403020);d.setGroupLocked(id,true);d.beginLayerProperties({id});d.previewLayerOpacity(.7);d.previewLayerName(U"locked");d.commitLayerOpacity();CHECK(d.findGroup(id)->opacity==.4&&d.findGroup(id)->name==U"locked");}
int main(){try{groupProperties();CHECK(normalizeLayerDisplayColor(-1,12.5,300,0)==0x00ff0d00);CHECK(normalizeLayerDisplayColor(0,0,0,0).has_value());CHECK(!normalizeLayerDisplayColor(NAN,0,0,255));CHECK(trimLayerDescription(U"\ufeff \t说明\n第二行\r\n\u3000")==U"说明\n第二行");CHECK(layerMetadataHistoryBytes({"a",{},U"\U0001f600"},{"a",{},U"x"},U"A",U"B")==69);Document d(1,1);d.markSaved();auto id=d.layer().id;auto revision=d.contentRevision(),history=d.historySize();auto owner=d.timeline().thumbnailStorage(d.cel().id).owner;d.beginLayerProperties();d.previewLayerDisplayColor(0u);d.previewLayerDescription(U" \ufeff说明\n第二行\u3000 ");CHECK(!d.dirty()&&d.historySize()==history&&d.contentRevision()==revision);d.commitLayerOpacity();CHECK(d.layer().displayColor==0&&d.layer().description==U"说明\n第二行"&&d.historySize()==history+1&&d.dirty()&&d.contentRevision()==revision);d.undo();CHECK(!d.layer().displayColor&&d.layer().description.empty()&&d.contentRevision()==revision);d.redo();CHECK(d.layer().displayColor==0&&d.timeline().thumbnailStorage(d.cel().id).owner==owner);auto encoded=project::encodeEditableProject(d);auto manifest=project::readProjectManifest(encoded.bytes);CHECK(manifest.layers[0].displayColor==0&&manifest.layers[0].description=="说明\n第二行");auto prepared=project::prepareEditableImport(manifest);CHECK(prepared.timeline.layers[0].description==U"说明\n第二行");auto h=d.historySize();d.beginLayerProperties();d.previewLayerDisplayColor(0xff112233u);d.previewLayerDescription(U"cancel");d.cancelLayerOpacity();CHECK(d.layer().displayColor==0&&d.historySize()==h);d.setLayerLocked(true);d.beginLayerProperties({id});d.previewLayerDisplayColor(0x80112233u);d.previewLayerDescription(U" locked ");d.commitLayerOpacity();CHECK(d.layer().locked&&d.layer().displayColor==0x80112233&&d.layer().description==U"locked"&&d.contentRevision()==revision);d.undo();CHECK(d.layer().displayColor==0);d.addLayer();auto second=d.layer().id;d.beginLayerProperties({second});d.previewLayerDescription(U"B");d.previewLayerDisplayColor(0xff556677u);d.commitLayerOpacity();d.beginLayerProperties({id,second});d.previewLayerDisplayColor({});d.commitLayerOpacity();CHECK(!d.layer().displayColor&&d.layer().description==U"B"&&d.timeline().state().layers[1].description==U"说明\n第二行");d.undo();CHECK(d.layer().displayColor==0xff556677u);std::cout<<"Layer metadata history/locked/batch/IO passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
